import { useCallback, useEffect, useMemo, useState } from 'react'
import { AdminEmptyState } from './AdminEmptyState'
import { useAdminSession } from './AdminSessionContext'
import { AdminShell } from './AdminShell'
import { canAdminWrite } from '@/data/admin-nav'
import { validateDownloadsContent } from '@/lib/admin/downloads-validation'
import { requestRevalidation } from '@/lib/admin/revalidate'
import { useUnsavedChangesGuard } from '@/lib/admin/use-unsaved-changes-guard'
import {
  DOWNLOADS_ID,
  defaultDownloadsContent,
  downloadPreviewOptions,
  normalizeDownloadsContent,
  type DownloadGroup,
  type DownloadItem,
  type DownloadsContent,
} from '@/lib/downloads'
