/*
 * Panel isi halaman /unduhan.
 *
 * Satu formulir, satu dokumen, satu tombol simpan — bukan daftar dokumen
 * seperti berita atau galeri. Alasannya bentuk datanya: yang disunting pengurus
 * bukan satu berkas melainkan SUSUNANNYA (kelompok apa saja, urutannya, mana
 * yang disembunyikan), dan susunan selalu lebih enak disunting utuh daripada
 * lewat sepuluh dokumen yang masing-masing menyimpan nomor urut sendiri. Kolom
 * kaki situs di /admin/settings memakai bentuk yang sama persis.
 *
 * Tidak memakai alur draft/publish seperti pengaturan situs. Pengaturan situs
 * punya draf karena satu salah ketik di sana mengubah setiap halaman sekaligus;
 * daftar unduhan cuma mengubah satu halaman, dan draf yang tidak pernah dipakai
 * hanya menambah satu tombol yang harus dipahami pengurus.
 *
 * ---- Kenapa barisnya terlipat ----
 *
 * Versi pertama panel ini membentangkan kedelapan isian SETIAP berkas
 * sekaligus. Dengan sembilan berkas itu berarti tujuh puluh dua kotak isian
 * berbaris tanpa jeda, dan untuk menemukan satu berkas pengurus harus membaca
 * semuanya satu per satu. Daftar berhenti jadi daftar; ia jadi tumpukan.
 *
 * Sekarang satu berkas = satu baris terlipat yang memuat persis apa yang
 * dipindai mata saat mencari: nomor, nama, cap format, dan status seperti yang
 * nanti dibaca pengunjung. Isiannya baru muncul saat barisnya dibuka — karena
 * menyunting selalu dikerjakan pada satu berkas, sementara mencari dikerjakan
 * pada seluruh daftar.
 *
 * Yang TIDAK bisa dikerjakan di sini, dan disengaja: mengunggah berkasnya
 * sendiri. Berkas unduhan tinggal di public/assets/unduhan/ di dalam repo, jadi
 * menambah berkas baru tetap butuh deploy. Panel ini mengelola DAFTARNYA. Untuk
 * berkas yang tidak ikut repo — buku panduan 52 MB, misalnya — pakai jenis
 * "Tautan luar" dan tunjuk ke Drive.
 */

type EditorTab = 'berkas' | 'teks'
type StatusFilter = 'semua' | 'siap' | 'menyusul' | 'tersembunyi'

const editorTabs: Array<{ id: EditorTab; label: string; number: string }> = [
  { id: 'berkas', label: 'Daftar berkas', number: '01' },
  { id: 'teks', label: 'Teks halaman', number: '02' },
]

function makeId(prefix: string) {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`
}

function moveItem<T>(items: T[], index: number, direction: -1 | 1) {
  const nextIndex = index + direction
  if (nextIndex < 0 || nextIndex >= items.length) return items
  const next = [...items]
  ;[next[index], next[nextIndex]] = [next[nextIndex], next[index]]
  return next
}

function emptyItem(): DownloadItem {
  return {
    id: makeId('berkas'),
    name: 'Berkas baru',
    desc: '',
    href: '',
    kind: 'file',
    format: 'PDF',
    note: '',
    preview: 'none',
    visible: true,
  }
}

function emptyGroup(): DownloadGroup {
  return { id: makeId('kelompok'), title: 'Kelompok baru', lead: '', visible: true, items: [] }
}

/**
 * Status satu berkas seperti yang akan terbaca pengunjung.
 *
 * Ukuran berkas TIDAK bisa dihitung di sini — ia dibaca dari disk saat halaman
 * dirender di server. Yang bisa dipastikan dari browser cuma jenis alamatnya,
 * dan itu sudah cukup untuk menjawab pertanyaan yang benar-benar ditanyakan
 * pengurus saat mengetik: "ini nanti muncul sebagai tautan hidup, atau sebagai
 * slot kosong?"
 */
function itemStatus(item: DownloadItem) {
  if (!item.href.trim()) return { tone: 'soon' as const, label: 'Menyusul' }
  if (item.kind === 'link') return { tone: 'link' as const, label: 'Tautan luar' }
  return { tone: 'file' as const, label: 'Berkas situs' }
}

function ChevronIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
      <path d="m9 6 6 6-6 6" />
    </svg>
  )
}

export function AdminDownloadsManager() {
  const session = useAdminSession()
  const canWrite = canAdminWrite(session.role)
  const [activeTab, setActiveTab] = useState<EditorTab>('berkas')
  const [values, setValues] = useState<DownloadsContent>(defaultDownloadsContent)
  const [loadedSnapshot, setLoadedSnapshot] = useState(JSON.stringify(defaultDownloadsContent))
  const [documentExists, setDocumentExists] = useState(false)
  const [isLoading, setIsLoading] = useState(hasFirebaseConfig())
  const [isSaving, setIsSaving] = useState(false)
  const [error, setError] = useState('')
  const [feedback, setFeedback] = useState('')
  const [saveAttempted, setSaveAttempted] = useState(false)

  /*
   * Yang sedang terbuka, disimpan sebagai daftar id.
   *
   * Bukan sebagai flag di dalam DownloadItem: "baris ini sedang kubuka" adalah
   * keadaan layar, bukan isi halaman, dan menaruhnya di data akan membuat
   * tombol simpan menyala hanya gara-gara pengurus mengintip satu baris.
   */
  const [openItems, setOpenItems] = useState<string[]>([])
  const [closedGroups, setClosedGroups] = useState<string[]>([])
  const [query, setQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('semua')

  useEffect(() => {
    if (!hasFirebaseConfig()) return
    let cancelled = false

    getContentDocument<DownloadsDocument>('downloads', DOWNLOADS_ID)
      .then((document) => {
        if (cancelled) return
        const content = normalizeDownloadsContent(document as Record<string, unknown> | null)
        setValues(content)
        setLoadedSnapshot(JSON.stringify(content))
        setDocumentExists(Boolean(document))
        setIsLoading(false)
      })
      .catch((loadError: unknown) => {
        if (cancelled) return
        setError(loadError instanceof Error ? loadError.message : 'Gagal memuat daftar unduhan.')
        setIsLoading(false)
      })

    return () => { cancelled = true }
  }, [])

  const validation = useMemo(() => validateDownloadsContent(values), [values])
  const isDirty = JSON.stringify(values) !== loadedSnapshot
  useUnsavedChangesGuard(canWrite && isDirty)

  /* Baris yang bermasalah selalu terbuka setelah tombol simpan ditekan.
     Pesan kesalahan yang menunjuk isian terlipat sama saja dengan menyuruh
     pengurus mencari sendiri apa yang salah. */
  const brokenItems = useMemo(
    () => new Set(validation.errors.map((issue) => issue.itemId).filter(Boolean) as string[]),
    [validation],
  )

  const counts = useMemo(() => {
    const all = values.groups.flatMap((group) => group.items.map((item) => ({ group, item })))
    const shown = all.filter(({ group, item }) => group.visible && item.visible)

    return {
      total: all.length,
      shown: shown.length,
      ready: shown.filter(({ item }) => item.href.trim()).length,
      soon: shown.filter(({ item }) => !item.href.trim()).length,
      hidden: all.length - shown.length,
    }
  }, [values])

  const matchesFilter = useCallback((group: DownloadGroup, item: DownloadItem) => {
    const needle = query.trim().toLowerCase()
    if (needle && !`${item.name} ${item.format} ${item.href} ${item.note}`.toLowerCase().includes(needle)) {
      return false
    }

    const isShown = group.visible && item.visible
    if (statusFilter === 'siap') return isShown && Boolean(item.href.trim())
    if (statusFilter === 'menyusul') return isShown && !item.href.trim()
    if (statusFilter === 'tersembunyi') return !isShown
    return true
  }, [query, statusFilter])

  const visibleCount = useMemo(
    () => values.groups.reduce((total, group) => total + group.items.filter((item) => matchesFilter(group, item)).length, 0),
    [values, matchesFilter],
  )

  function clearMessages() { setFeedback(''); setError('') }

  function updateField<Key extends keyof DownloadsContent>(key: Key, value: DownloadsContent[Key]) {
    setValues((current) => ({ ...current, [key]: value }))
    clearMessages()
  }

  function updateGroup(index: number, patch: Partial<DownloadGroup>) {
    updateField('groups', values.groups.map((group, groupIndex) => groupIndex === index ? { ...group, ...patch } : group))
  }

  function updateItem(groupIndex: number, itemIndex: number, patch: Partial<DownloadItem>) {
    const group = values.groups[groupIndex]
    updateGroup(groupIndex, {
      items: group.items.map((item, index) => index === itemIndex ? { ...item, ...patch } : item),
    })
  }

  function toggleItem(id: string) {
    setOpenItems((current) => current.includes(id) ? current.filter((entry) => entry !== id) : [...current, id])
  }

  function toggleGroup(id: string) {
    setClosedGroups((current) => current.includes(id) ? current.filter((entry) => entry !== id) : [...current, id])
  }

  function addItem(groupIndex: number) {
    const item = emptyItem()
    updateGroup(groupIndex, { items: [...values.groups[groupIndex].items, item] })
    // Berkas baru dibuka sendiri: menambah sesuatu lalu tidak melihat apa pun
    // berubah terbaca sebagai tombol yang rusak.
    setOpenItems((current) => [...current, item.id])
  }

  async function save() {
    setSaveAttempted(true)
    clearMessages()

    if (!validation.success) {
      const first = validation.errors[0]
      setActiveTab(first.tab)
      if (first.itemId) setOpenItems((current) => current.includes(first.itemId!) ? current : [...current, first.itemId!])
      if (first.groupId) setClosedGroups((current) => current.filter((entry) => entry !== first.groupId))
      setError(`Penyimpanan ditahan. Perbaiki ${validation.errors.length} isian yang belum valid.`)
      return
    }

    setIsSaving(true)
    // Dinormalkan sebelum ditulis, bukan sesudah dibaca. Dokumen ini terbaca
    // publik, jadi yang tersimpan di Firestore harus sudah bentuk akhirnya —
    // termasuk href yang skemanya ditolak dan cap format yang dipendekkan.
    const content = normalizeDownloadsContent(values as unknown as Record<string, unknown>)

    try {
      await writeContentDocumentAtId<DownloadsDocument>(
        'downloads', DOWNLOADS_ID, { ...content, updatedBy: session.email }, documentExists,
      )
      await requestRevalidation('downloads')
      setValues(content)
      setLoadedSnapshot(JSON.stringify(content))
      setDocumentExists(true)
      setSaveAttempted(false)
      setFeedback('Daftar unduhan tersimpan dan halaman /unduhan sedang disegarkan.')
    } catch (saveError) {
      setError(saveError instanceof Error ? saveError.message : 'Gagal menyimpan daftar unduhan.')
    } finally {
      setIsSaving(false)
    }
  }

  function focusIssue(issue: { tab: EditorTab; itemId?: string; groupId?: string }) {
    setActiveTab(issue.tab)
    if (issue.groupId) setClosedGroups((current) => current.filter((entry) => entry !== issue.groupId))
    if (issue.itemId) setOpenItems((current) => current.includes(issue.itemId!) ? current : [...current, issue.itemId!])
  }

  return (
    <AdminShell
      activeHref="/admin/downloads"
      description="Kelola berkas yang bisa diunduh publik di halaman /unduhan: lambang, dokumen resmi, dan template kegiatan."
      kicker="Publikasi"
      title="Berkas unduhan"
    >
      {!hasFirebaseConfig() ? (
        <AdminEmptyState body="Isi .env.local sesuai FIREBASE_SETUP.md agar daftar unduhan dapat dimuat." kicker="Konfigurasi" title="Firebase belum siap." />
      ) : isLoading ? (
        <AdminEmptyState body="Mohon tunggu sebentar." kicker="Memuat" title="Mengambil daftar berkas..." />
      ) : (
        <div className="admin-settings-workspace">
          {!canWrite ? <p className="admin-form-error" role="status">Peran kamu hanya bisa melihat. Isian dikunci.</p> : null}

          <section className="admin-settings-status" aria-label="Ringkasan daftar">
            <div>
              <span className={`admin-settings-status-dot ${isDirty ? 'is-draft' : 'is-live'}`} />
              <div>
                <small>Status dokumen</small>
                <strong>{isDirty ? 'Perubahan belum disimpan' : 'Sinkron dengan halaman publik'}</strong>
              </div>
            </div>
            <dl>
              <div><dt>Tampil di halaman</dt><dd>{counts.shown} berkas</dd></div>
              <div><dt>Sudah ada alamatnya</dt><dd>{counts.ready}</dd></div>
              <div><dt>Menyusul</dt><dd>{counts.soon}</dd></div>
              <div><dt>Disembunyikan</dt><dd>{counts.hidden}</dd></div>
            </dl>
          </section>

          <div className="admin-settings-layout">
            <aside className="admin-settings-tabs" role="tablist" aria-label="Bagian halaman unduhan">
              {editorTabs.map((tab) => (
                <button
                  key={tab.id}
                  type="button"
                  role="tab"
                  aria-selected={activeTab === tab.id}
                  data-invalid={saveAttempted && validation.errors.some((issue) => issue.tab === tab.id)}
                  className={activeTab === tab.id ? 'is-active' : ''}
                  onClick={() => setActiveTab(tab.id)}
                >
                  <span>{tab.number}</span>{tab.label}
                </button>
              ))}
            </aside>

            <form className="admin-settings-editor" onSubmit={(event) => event.preventDefault()}>
              {activeTab === 'berkas' ? (
                <FilesEditor
                  values={values}
                  disabled={!canWrite}
                  brokenItems={saveAttempted ? brokenItems : new Set<string>()}
                  closedGroups={closedGroups}
                  openItems={openItems}
                  query={query}
                  statusFilter={statusFilter}
                  visibleCount={visibleCount}
                  counts={counts}
                  matchesFilter={matchesFilter}
                  onQueryChange={setQuery}
                  onStatusFilterChange={setStatusFilter}
                  onToggleItem={toggleItem}
                  onToggleGroup={toggleGroup}
                  onSetOpenItems={setOpenItems}
                  onAddItem={addItem}
                  updateField={updateField}
                  updateGroup={updateGroup}
                  updateItem={updateItem}
                />
              ) : (
                <CopyEditor values={values} disabled={!canWrite} updateField={updateField} />
              )}

              {saveAttempted && validation.errors.length > 0 ? (
                <div className="admin-validation-summary" role="alert">
                  <strong>Daftar belum siap disimpan.</strong>
                  <ul>
                    {validation.errors.map((issue, index) => (
                      <li key={`${issue.tab}-${index}`}>
                        <button type="button" onClick={() => focusIssue(issue)}>{issue.message}</button>
                      </li>
                    ))}
                  </ul>
                </div>
              ) : null}

              {/*
                Peringatan ditampilkan tanpa menunggu tombol simpan ditekan, dan
                tidak pernah menahan penyimpanan. Isinya hal yang memang boleh
                dibiarkan begitu — terutama berkas yang sengaja didaftarkan
                lebih dulu sebelum ada wujudnya.
              */}
              {validation.warnings.length > 0 ? (
                <div className="admin-validation-summary is-warning" role="status">
                  <strong>{validation.warnings.length} catatan, bukan penghalang.</strong>
                  <ul>
                    {validation.warnings.map((issue, index) => (
                      <li key={`warn-${index}`}>
                        {issue.itemId
                          ? <button type="button" onClick={() => focusIssue(issue)}>{issue.message}</button>
                          : issue.message}
                      </li>
                    ))}
                  </ul>
                </div>
              ) : null}

              {error ? <p className="admin-form-error" role="alert">{error}</p> : null}
              {feedback ? <p className="admin-form-success" role="status">{feedback}</p> : null}

              <footer className="admin-settings-actions">
                <div>
                  <strong>{isDirty ? 'Ada perubahan belum disimpan' : 'Tidak ada perubahan'}</strong>
                  <span>Menyimpan langsung menerbitkan ke /unduhan dan tercatat di riwayat perubahan.</span>
                </div>
                <a className="admin-secondary-button" href="/unduhan" target="_blank" rel="noopener noreferrer">
                  Lihat halaman publik
                </a>
                <button
                  className="admin-primary-button"
                  type="button"
                  disabled={!canWrite || isSaving || !isDirty}
                  onClick={() => void save()}
                >
                  {isSaving ? 'Menyimpan...' : 'Simpan & terbitkan'}
                </button>
              </footer>
            </form>
          </div>
        </div>
      )}
    </AdminShell>
  )
}

type FieldSetter = <Key extends keyof DownloadsContent>(key: Key, value: DownloadsContent[Key]) => void

function SectionHeader({ number, label, title, body }: { number: string; label: string; title: string; body: string }) {
  return <header><span>{number} / {label}</span><h2>{title}</h2><p>{body}</p></header>
}

function FilesEditor({
  values,
  disabled,
  brokenItems,
  closedGroups,
  openItems,
  query,
  statusFilter,
  visibleCount,
  counts,
  matchesFilter,
  onQueryChange,
  onStatusFilterChange,
  onToggleItem,
  onToggleGroup,
  onSetOpenItems,
  onAddItem,
  updateField,
  updateGroup,
  updateItem,
}: {
  values: DownloadsContent
  disabled: boolean
  brokenItems: Set<string>
  closedGroups: string[]
  openItems: string[]
  query: string
  statusFilter: StatusFilter
  visibleCount: number
  counts: { total: number; shown: number; ready: number; soon: number; hidden: number }
  matchesFilter: (group: DownloadGroup, item: DownloadItem) => boolean
  onQueryChange: (value: string) => void
  onStatusFilterChange: (value: StatusFilter) => void
  onToggleItem: (id: string) => void
  onToggleGroup: (id: string) => void
  onSetOpenItems: (updater: (current: string[]) => string[]) => void
  onAddItem: (groupIndex: number) => void
  updateField: FieldSetter
  updateGroup: (index: number, patch: Partial<DownloadGroup>) => void
  updateItem: (groupIndex: number, itemIndex: number, patch: Partial<DownloadItem>) => void
}) {
  const allIds = values.groups.flatMap((group) => group.items.map((item) => item.id))
  const isEverythingOpen = allIds.length > 0 && allIds.every((id) => openItems.includes(id))
  const isFiltering = query.trim().length > 0 || statusFilter !== 'semua'

  const filters: Array<{ id: StatusFilter; label: string; count: number }> = [
    { id: 'semua', label: 'Semua', count: counts.total },
    { id: 'siap', label: 'Siap', count: counts.ready },
    { id: 'menyusul', label: 'Menyusul', count: counts.soon },
    { id: 'tersembunyi', label: 'Disembunyikan', count: counts.hidden },
  ]

  return (
    <section className="admin-settings-section">
      <SectionHeader
        number="01"
        label="Daftar berkas"
        title="Apa saja yang boleh diambil publik?"
        body="Berkas situs harus sudah ada di public/assets/unduhan/ (butuh deploy). Berkas besar seperti buku panduan lebih baik ditaruh di Drive dan didaftarkan sebagai tautan luar."
      />

      <div className="admin-dl-toolbar">
        <label className="admin-dl-search">
          <span className="sr-only">Cari berkas</span>
          <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round">
            <circle cx="11" cy="11" r="7" /><path d="m20 20-3.6-3.6" />
          </svg>
          <input value={query} placeholder="Cari nama, format, atau alamat berkas..." onChange={(event) => onQueryChange(event.target.value)} />
        </label>

        <div className="admin-dl-filters" role="group" aria-label="Saring berdasarkan status">
          {filters.map((filter) => (
            <button
              key={filter.id}
              type="button"
              aria-pressed={statusFilter === filter.id}
              onClick={() => onStatusFilterChange(filter.id)}
            >
              {filter.label}<i>{filter.count}</i>
            </button>
          ))}
        </div>

        <button
          className="admin-dl-expand"
          type="button"
          onClick={() => onSetOpenItems(() => (isEverythingOpen ? [] : allIds))}
        >
          {isEverythingOpen ? 'Tutup semua' : 'Buka semua'}
        </button>
      </div>

      {isFiltering ? (
        <p className="admin-dl-result" role="status">
          {visibleCount === 0
            ? 'Tidak ada berkas yang cocok. Kosongkan pencarian untuk melihat daftar penuh.'
            : `${visibleCount} dari ${counts.total} berkas cocok.`}
        </p>
      ) : null}

      <div className="admin-dl-groups">
        {values.groups.map((group, groupIndex) => {
          const isOpen = !closedGroups.includes(group.id)
          const matched = group.items.filter((item) => matchesFilter(group, item))
          const readyCount = group.items.filter((item) => item.href.trim()).length

          // Saat sedang menyaring, kelompok tanpa satu pun kecocokan
          // disingkirkan seluruhnya: judul kelompok yang menggantung di atas
          // ruang kosong terbaca sebagai hasil, padahal bukan.
          if (isFiltering && matched.length === 0) return null

          return (
            <article className="admin-dl-group" key={group.id} data-open={isOpen} data-hidden={!group.visible || undefined}>
              <header className="admin-dl-group-head">
                <button
                  className="admin-dl-group-summary"
                  type="button"
                  aria-expanded={isOpen}
                  onClick={() => onToggleGroup(group.id)}
                >
                  <ChevronIcon />
                  <i className="admin-dl-group-no">{String(groupIndex + 1).padStart(2, '0')}</i>
                  <b>{group.title.trim() || 'Kelompok tanpa judul'}</b>
                  <em>
                    {group.items.length} berkas · {readyCount} siap
                    {group.visible ? '' : ' · kelompok disembunyikan'}
                  </em>
                </button>

                <div className="admin-dl-group-tools">
                  <Visibility checked={group.visible} disabled={disabled} onChange={(visible) => updateGroup(groupIndex, { visible })} />
                  <RowActions
                    disabled={disabled}
                    index={groupIndex}
                    label={group.title.trim() || `kelompok ${groupIndex + 1}`}
                    length={values.groups.length}
                    onMove={(direction) => updateField('groups', moveItem(values.groups, groupIndex, direction))}
                    onDelete={() => updateField('groups', values.groups.filter((_, index) => index !== groupIndex))}
                  />
                </div>
              </header>

              <div className="admin-dl-group-body" hidden={!isOpen}>
                <div className="admin-dl-group-fields">
                  <label>
                    <span>Judul kelompok</span>
                    <input disabled={disabled} value={group.title} onChange={(event) => updateGroup(groupIndex, { title: event.target.value })} />
                  </label>
                  <label>
                    <span>Pengantar</span>
                    <input
                      disabled={disabled}
                      placeholder="Satu kalimat pengantar (boleh dikosongkan)."
                      value={group.lead}
                      onChange={(event) => updateGroup(groupIndex, { lead: event.target.value })}
                    />
                  </label>
                </div>

                <div className="admin-dl-rows">
                  {group.items.map((item, itemIndex) => {
                    if (!matchesFilter(group, item)) return null

                    const status = itemStatus(item)
                    const isItemOpen = openItems.includes(item.id) || brokenItems.has(item.id)
                    const isBroken = brokenItems.has(item.id)

                    return (
                      <div
                        className="admin-dl-row"
                        key={item.id}
                        data-open={isItemOpen}
                        data-hidden={!item.visible || undefined}
                        data-invalid={isBroken || undefined}
                      >
                        <div className="admin-dl-row-head">
                          <button
                            className="admin-dl-row-summary"
                            type="button"
                            aria-expanded={isItemOpen}
                            onClick={() => onToggleItem(item.id)}
                          >
                            <ChevronIcon />
                            <i className="admin-dl-row-no">{String(itemIndex + 1).padStart(2, '0')}</i>
                            <b>{item.name.trim() || 'Berkas tanpa nama'}</b>
                            <span className="admin-dl-format-chip">{item.format || '—'}</span>
                            <span className="admin-dl-status" data-tone={status.tone}>{status.label}</span>
                          </button>

                          <div className="admin-dl-row-tools">
                            <Visibility checked={item.visible} disabled={disabled} onChange={(visible) => updateItem(groupIndex, itemIndex, { visible })} />
                            <RowActions
                              disabled={disabled}
                              index={itemIndex}
                              label={item.name.trim() || `berkas ${itemIndex + 1}`}
                              length={group.items.length}
                              onMove={(direction) => updateGroup(groupIndex, { items: moveItem(group.items, itemIndex, direction) })}
                              onDelete={() => updateGroup(groupIndex, { items: group.items.filter((_, index) => index !== itemIndex) })}
                            />
                          </div>
                        </div>

                        <div className="admin-dl-row-body" hidden={!isItemOpen}>
                          <div className="admin-dl-field-grid">
                            <label>
                              <span>Nama berkas</span>
                              <input disabled={disabled} value={item.name} onChange={(event) => updateItem(groupIndex, itemIndex, { name: event.target.value })} />
                            </label>

                            <label>
                              <span>Cap format</span>
                              <input
                                className="admin-dl-format"
                                disabled={disabled}
                                maxLength={6}
                                value={item.format}
                                onChange={(event) => updateItem(groupIndex, itemIndex, { format: event.target.value.toUpperCase() })}
                              />
                            </label>

                            <label>
                              <span>Jenis</span>
                              <select
                                disabled={disabled}
                                value={item.kind}
                                onChange={(event) => updateItem(groupIndex, itemIndex, { kind: event.target.value as DownloadItem['kind'] })}
                              >
                                <option value="file">Berkas situs</option>
                                <option value="link">Tautan luar</option>
                              </select>
                            </label>

                            <label className="admin-dl-href">
                              <span>{item.kind === 'link' ? 'URL lengkap' : 'Path di dalam situs'}</span>
                              <input
                                disabled={disabled}
                                value={item.href}
                                placeholder={item.kind === 'link' ? 'https://drive.google.com/...' : '/assets/unduhan/nama-berkas.pdf'}
                                onChange={(event) => updateItem(groupIndex, itemIndex, { href: event.target.value })}
                              />
                              <small>
                                {item.kind === 'link'
                                  ? 'Dibuka di tab baru. Pastikan izin berbaginya publik.'
                                  : 'Ukuran berkas dihitung otomatis saat halaman dirender. Kosongkan kalau berkasnya belum ada.'}
                              </small>
                            </label>

                            <label>
                              <span>Pratinjau</span>
                              <select
                                disabled={disabled || item.kind === 'link'}
                                value={item.preview}
                                onChange={(event) => updateItem(groupIndex, itemIndex, { preview: event.target.value as DownloadItem['preview'] })}
                              >
                                {downloadPreviewOptions.map((option) => (
                                  <option key={option.value} value={option.value}>{option.label}</option>
                                ))}
                              </select>
                              <small>Hanya untuk berkas gambar. Plat tampil besar di puncak halaman.</small>
                            </label>

                            <label>
                              <span>Catatan kecil</span>
                              <input
                                disabled={disabled}
                                placeholder="mis. Vektor, latar transparan"
                                value={item.note}
                                onChange={(event) => updateItem(groupIndex, itemIndex, { note: event.target.value })}
                              />
                            </label>

                            <label className="admin-dl-desc">
                              <span>Keterangan</span>
                              <textarea
                                rows={2}
                                disabled={disabled}
                                value={item.desc}
                                onChange={(event) => updateItem(groupIndex, itemIndex, { desc: event.target.value })}
                              />
                            </label>
                          </div>
                        </div>
                      </div>
                    )
                  })}

                  {group.items.length === 0 ? (
                    <p className="admin-dl-empty">Kelompok ini masih kosong.</p>
                  ) : null}
                </div>

                <button className="admin-inline-add" type="button" disabled={disabled} onClick={() => onAddItem(groupIndex)}>
                  + Tambah berkas
                </button>
              </div>
            </article>
          )
        })}
      </div>

      <button
        className="admin-secondary-button"
        type="button"
        disabled={disabled}
        onClick={() => updateField('groups', [...values.groups, emptyGroup()])}
      >
        + Tambah kelompok
      </button>
    </section>
  )
}

function CopyEditor({
  values,
  disabled,
  updateField,
}: {
  values: DownloadsContent
  disabled: boolean
  updateField: FieldSetter
}) {
  return (
    <section className="admin-settings-section">
      <SectionHeader
        number="02"
        label="Teks halaman"
        title="Kalimat pembuka, aturan pakai, dan ajakan penutup."
        body="Bagian pratinjau lambang hanya tampil kalau ada berkas gambar yang ditandai sebagai plat."
      />

      <div className="admin-settings-grid two-column compact">
        <label><span>Kicker</span><input disabled={disabled} value={values.heroKicker} onChange={(e) => updateField('heroKicker', e.target.value)} /><small>Ditulis bersama nama kabinet.</small></label>
        <label><span>Judul</span><input disabled={disabled} value={values.heroTitle} onChange={(e) => updateField('heroTitle', e.target.value)} /></label>
        <label><span>Lanjutan judul (emas)</span><input disabled={disabled} value={values.heroHighlight} onChange={(e) => updateField('heroHighlight', e.target.value)} /><small>Boleh dikosongkan.</small></label>
      </div>
      <label className="admin-settings-wide-field"><span>Pengantar</span><textarea rows={3} disabled={disabled} value={values.heroLead} onChange={(e) => updateField('heroLead', e.target.value)} /></label>

      <div className="admin-settings-grid two-column compact">
        <label><span>Judul bagian pratinjau</span><input disabled={disabled} value={values.brandTitle} onChange={(e) => updateField('brandTitle', e.target.value)} /></label>
        <label><span>Judul daftar aturan</span><input disabled={disabled} value={values.rulesTitle} onChange={(e) => updateField('rulesTitle', e.target.value)} /></label>
      </div>
      <label className="admin-settings-wide-field"><span>Pengantar bagian pratinjau</span><textarea rows={2} disabled={disabled} value={values.brandLead} onChange={(e) => updateField('brandLead', e.target.value)} /></label>

      <div className="admin-structure-list">
        {values.rules.map((rule, index) => (
          <div className="admin-structure-row dl-rule-row" key={`rule-${index}`}>
            <span className="admin-structure-index">{String(index + 1).padStart(2, '0')}</span>
            <input
              aria-label={`Aturan ${index + 1}`}
              disabled={disabled}
              value={rule}
              onChange={(event) => updateField('rules', values.rules.map((current, currentIndex) => currentIndex === index ? event.target.value : current))}
            />
            <RowActions
              disabled={disabled}
              index={index}
              label={`aturan ${index + 1}`}
              length={values.rules.length}
              onMove={(direction) => updateField('rules', moveItem(values.rules, index, direction))}
              onDelete={() => updateField('rules', values.rules.filter((_, currentIndex) => currentIndex !== index))}
            />
          </div>
        ))}
      </div>
      <button className="admin-inline-add" type="button" disabled={disabled} onClick={() => updateField('rules', [...values.rules, 'Aturan baru'])}>
        + Tambah aturan
      </button>

      <label className="admin-settings-wide-field"><span>Judul ajakan penutup</span><input disabled={disabled} value={values.askTitle} onChange={(e) => updateField('askTitle', e.target.value)} /></label>
      <label className="admin-settings-wide-field"><span>Isi ajakan penutup</span><textarea rows={3} disabled={disabled} value={values.askBody} onChange={(e) => updateField('askBody', e.target.value)} /></label>
    </section>
  )
}

function Visibility({ checked, disabled, onChange }: { checked: boolean; disabled: boolean; onChange: (value: boolean) => void }) {
  return <label className="admin-visibility-toggle"><input type="checkbox" disabled={disabled} checked={checked} onChange={(event) => onChange(event.target.checked)} /><span>Tampil</span></label>
}

/**
 * Tombol urut dan hapus untuk satu baris.
 *
 * Setiap tombol menyebut apa yang dikenainya. Di daftar berpuluh baris,
 * pembaca layar yang menemukan sembilan tombol bernama "Hapus" tidak bisa
 * membedakan mana yang menghapus apa.
 */
function RowActions({
  disabled,
  index,
  label,
  length,
  onMove,
  onDelete,
}: {
  disabled: boolean
  index: number
  label: string
  length: number
  onMove: (direction: -1 | 1) => void
  onDelete: () => void
}) {
  return (
    <div className="admin-row-actions">
      <button type="button" aria-label={`Naikkan ${label}`} title="Naikkan" disabled={disabled || index === 0} onClick={() => onMove(-1)}>↑</button>
      <button type="button" aria-label={`Turunkan ${label}`} title="Turunkan" disabled={disabled || index === length - 1} onClick={() => onMove(1)}>↓</button>
      <button type="button" aria-label={`Hapus ${label}`} disabled={disabled} onClick={onDelete}>Hapus</button>
    </div>
  )
}
