/*
 * Model isi halaman /unduhan.
 *
 * Murni. Tidak ada Firebase, tidak ada node:fs, tidak ada React — karena berkas
 * ini dipakai tiga pihak sekaligus: halaman publik di server, panel admin di
 * browser, dan tes. Begitu salah satu impor di sini menarik Firebase SDK, panel
 * ikut membawanya ke bundle klien tanpa alasan.
 *
 * Nilai bawaan di bawah adalah keadaan awal halaman, bukan isinya yang
 * sebenarnya. Yang sebenarnya tinggal di Firestore `downloads/index` dan disunting
 * pengurus lewat /admin/downloads. Bawaan ini yang dipakai kalau dokumen itu
 * belum pernah dibuat, sama seperti defaultSiteSettings di site-settings.ts.
 */

/**
 * Id dokumen tunggal tempat isi halaman /unduhan tinggal.
 *
 * Tinggal DI SINI, bukan di downloads-data.ts bersama pembacanya, dan itu
 * pelajaran yang dibayar sekali: panel admin adalah komponen klien, dan
 * mengimpor satu tetapan dari berkas yang juga mengimpor node:fs menarik seluruh
 * berkas itu ke bundle browser. Webpack tidak bisa menyelesaikan skema `node:`
 * untuk klien, jadi seluruh halaman panelnya gagal dibangun — demi satu string.
 */
export const DOWNLOADS_ID = 'index'

export type DownloadKind =
  /** Berkas yang tinggal di repo, di bawah public/. Ukurannya dihitung dari disk. */
  | 'file'
  /** Berkas yang tinggal di luar (Drive, dsb). Dibuka di tab baru. */
  | 'link'

/**
 * Bagaimana berkas ini dipratinjau di puncak halaman.
 *
 * Halaman unduhan logo yang tidak menampilkan logonya memaksa orang mengunduh
 * dulu baru tahu ia mengambil yang mana. Berkas gambar bisa dipasang sebagai
 * plat besar di atas latar tempat ia memang dipakai:
 *
 *   none   tidak dipratinjau, cukup jadi baris daftar
 *   navy   plat gelap, untuk berkas yang dipakai di atas latar navy
 *   paper  plat terang berpapan catur, supaya latar transparan terlihat
 */
export type DownloadPreview = 'none' | 'navy' | 'paper'

export const downloadPreviewOptions: Array<{ value: DownloadPreview; label: string }> = [
  { value: 'none', label: 'Tidak dipratinjau' },
  { value: 'navy', label: 'Plat gelap' },
  { value: 'paper', label: 'Plat terang' },
]

export type DownloadItem = {
  id: string
  name: string
  desc: string
  /**
   * Untuk `file`: path absolut dari root situs, mis. '/assets/unduhan/logo.svg'.
   * Untuk `link`: URL penuh.
   * Kosong berarti berkasnya memang belum ada, dan barisnya tampil sebagai slot
   * bertanda "Menyusul" — bukan sebagai tautan mati.
   */
  href: string
  kind: DownloadKind
  /** Ditulis pendek dan huruf besar: SVG, PNG, PDF, ZIP, DOCX, TEX. */
  format: string
  /** Satu frasa, bukan kalimat. Muncul sebagai keterangan kecil di baris. */
  note: string
  preview: DownloadPreview
  visible: boolean
}

export type DownloadGroup = {
  id: string
  title: string
  lead: string
  visible: boolean
  items: DownloadItem[]
}

export type DownloadsContent = {
  heroKicker: string
  heroTitle: string
  /** Bagian judul yang diberi warna emas. */
  heroHighlight: string
  heroLead: string
  brandTitle: string
  brandLead: string
  rulesTitle: string
  rules: string[]
  askTitle: string
  askBody: string
  groups: DownloadGroup[]
}

