/*
 * Batas jumlah. Ada bukan karena ada yang akan mengetik 400 grup, melainkan
 * karena dokumen Firestore dibaca setiap kali halaman dirender: satu isian
 * kacau tidak boleh bisa membuat halaman publik memuat berkas satu megabita.
 */
const MAX_GROUPS = 12
const MAX_ITEMS = 24
const MAX_RULES = 8

function pickText(value: unknown, fallback: string) {
  return typeof value === 'string' && value.trim() ? value.trim() : fallback
}

function pickOptionalText(value: unknown) {
  return typeof value === 'string' ? value.trim() : ''
}

function pickBoolean(value: unknown, fallback: boolean) {
  return typeof value === 'boolean' ? value : fallback
}

function normalizeId(value: unknown, fallback: string) {
  const id = pickOptionalText(value).replace(/[^a-z0-9_-]/gi, '-').slice(0, 80)
  return id || fallback
}

/**
 * Alamat berkas yang boleh dipakai.
 *
 * Hanya path internal atau http(s). Kosong itu sah — artinya berkasnya belum
 * ada. Yang ditolak adalah skema lain, terutama `javascript:`: isian ini
 * berakhir di atribut href sebuah tautan, dan satu akun editor yang dibajak
 * tidak boleh bisa menanam skrip di halaman publik lewat sini.
 */
function normalizeHref(value: unknown) {
  const href = pickOptionalText(value)
  if (!href) return ''
  return /^(https?:\/\/|\/)/i.test(href) ? href.slice(0, 2048) : ''
}

function normalizePreview(value: unknown): DownloadPreview {
  return value === 'navy' || value === 'paper' ? value : 'none'
}

function normalizeKind(value: unknown): DownloadKind {
  return value === 'link' ? 'link' : 'file'
}

/** Cap format selalu huruf besar dan pendek: ia dibaca sebagai simbol, bukan kata. */
function normalizeFormat(value: unknown, fallback: string) {
  const format = pickOptionalText(value).toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 6)
  return format || fallback
}

function normalizeItem(raw: unknown, index: number): DownloadItem {
  const record = raw && typeof raw === 'object' ? (raw as Record<string, unknown>) : {}

  return {
    id: normalizeId(record.id, `berkas-${index + 1}`),
    name: pickText(record.name, 'Berkas tanpa nama'),
    desc: pickOptionalText(record.desc).slice(0, 400),
    href: normalizeHref(record.href),
    kind: normalizeKind(record.kind),
    format: normalizeFormat(record.format, 'FILE'),
    note: pickOptionalText(record.note).slice(0, 120),
    preview: normalizePreview(record.preview),
    visible: pickBoolean(record.visible, true),
  }
}

function normalizeGroup(raw: unknown, index: number): DownloadGroup {
  const record = raw && typeof raw === 'object' ? (raw as Record<string, unknown>) : {}
  const items = Array.isArray(record.items) ? record.items.slice(0, MAX_ITEMS) : []

  return {
    id: normalizeId(record.id, `kelompok-${index + 1}`),
    title: pickText(record.title, 'Kelompok tanpa judul'),
    lead: pickOptionalText(record.lead).slice(0, 400),
    visible: pickBoolean(record.visible, true),
    items: items.map(normalizeItem),
  }
}

function normalizeRules(value: unknown, fallback: string[]) {
  if (!Array.isArray(value)) return fallback

  const rules = value
    .slice(0, MAX_RULES)
    .map((rule) => pickOptionalText(rule).slice(0, 300))
    .filter(Boolean)

  /*
   * Daftar kosong TIDAK jatuh ke bawaan, dan itu disengaja: menghapus semua
   * aturan adalah keputusan yang sah ("kami belum punya panduan merek"), dan
   * memunculkannya kembali diam-diam berarti panel berbohong tentang apa yang
   * tersimpan. Yang jatuh ke bawaan hanya field yang bukan array sama sekali.
   */
  return rules
}

export function normalizeDownloadsContent(
  raw: Record<string, unknown> | null | undefined,
): DownloadsContent {
  if (!raw) return defaultDownloadsContent

  const groups = Array.isArray(raw.groups)
    ? raw.groups.slice(0, MAX_GROUPS).map(normalizeGroup)
    : defaultDownloadsContent.groups

  return {
    heroKicker: pickText(raw.heroKicker, defaultDownloadsContent.heroKicker),
    heroTitle: pickText(raw.heroTitle, defaultDownloadsContent.heroTitle),
    heroHighlight: pickOptionalText(raw.heroHighlight),
    heroLead: pickText(raw.heroLead, defaultDownloadsContent.heroLead),
    brandTitle: pickText(raw.brandTitle, defaultDownloadsContent.brandTitle),
    brandLead: pickOptionalText(raw.brandLead),
    rulesTitle: pickText(raw.rulesTitle, defaultDownloadsContent.rulesTitle),
    rules: normalizeRules(raw.rules, defaultDownloadsContent.rules),
    askTitle: pickText(raw.askTitle, defaultDownloadsContent.askTitle),
    askBody: pickText(raw.askBody, defaultDownloadsContent.askBody),
    groups,
  }
}

/** Semua berkas dari semua kelompok yang tampil, diratakan. */
export function visibleDownloadItems(content: DownloadsContent): DownloadItem[] {
  return content.groups
    .filter((group) => group.visible)
    .flatMap((group) => group.items.filter((item) => item.visible))
}
