import type { DownloadItem, DownloadsContent } from '@/lib/downloads'

/*
 * Pemeriksaan sebelum daftar unduhan disimpan.
 *
 * Yang diperiksa di sini SEMUANYA soal yang tidak bisa dilihat pengurus dari
 * formulir. Bahwa judulnya kosong terlihat sendiri; bahwa berkas PNG diberi
 * pratinjau lalu alamatnya diisi tautan Drive tidak terlihat sampai halaman
 * publiknya terbit dengan kotak gambar rusak.
 *
 * Peringatan dipisah dari kesalahan, dan itu bukan hiasan. Berkas yang belum
 * punya alamat adalah keadaan yang SAH dan memang dirancang — barisnya tampil
 * sebagai slot "Menyusul". Menolak simpan karenanya akan memaksa pengurus
 * menghapus rencananya sendiri hanya supaya tombol simpan menyala.
 */

export type DownloadsValidationIssue = {
  tab: 'berkas' | 'teks'
  level: 'error' | 'warning'
  message: string
  /*
   * Baris yang bersangkutan, kalau masalahnya memang milik satu baris.
   *
   * Ini bukan kemewahan. Di panel, baris berkas terlipat sampai diklik, jadi
   * pesan "alamat X harus dimulai dengan /" bisa menunjuk isian yang sedang
   * tidak terlihat. Id inilah yang dipakai panel untuk membuka baris itu
   * sendiri dan menandainya, supaya pesan kesalahan tidak pernah menyuruh
   * pengurus mencari sendiri.
   */
  itemId?: string
  groupId?: string
}

const IMAGE_EXTENSIONS = ['.svg', '.png', '.jpg', '.jpeg', '.webp', '.avif', '.gif']

function isImagePath(href: string) {
  const clean = href.split('?')[0].toLowerCase()
  return IMAGE_EXTENSIONS.some((extension) => clean.endsWith(extension))
}

function isHttpUrl(value: string) {
  try {
    const parsed = new URL(value.trim())
    return parsed.protocol === 'https:' || parsed.protocol === 'http:'
  } catch {
    return false
  }
}

function label(item: DownloadItem) {
  return item.name.trim() || 'tanpa nama'
}

export function validateDownloadsContent(content: DownloadsContent) {
  const issues: DownloadsValidationIssue[] = []
  const seenIds = new Set<string>()

  const error = (message: string, tab: DownloadsValidationIssue['tab'] = 'berkas') =>
    issues.push({ tab, level: 'error', message })
  // Varian yang tahu baris mana yang dibicarakan. Dipisah dari `error` supaya
  // pemeriksaan yang memang bukan milik satu baris — judul halaman, misalnya —
  // tidak terpaksa mengarang id. Semua peringatan kebetulan milik satu baris,
  // jadi tidak ada `warn` tanpa id.
  const itemError = (item: DownloadItem, groupId: string, message: string) =>
    issues.push({ tab: 'berkas', level: 'error', message, itemId: item.id, groupId })
  const itemWarn = (item: DownloadItem, groupId: string, message: string) =>
    issues.push({ tab: 'berkas', level: 'warning', message, itemId: item.id, groupId })

  if (!content.heroTitle.trim()) error('Judul halaman wajib diisi.', 'teks')
  if (!content.askTitle.trim()) error('Judul ajakan di kaki halaman wajib diisi.', 'teks')

  content.groups.forEach((group) => {
    if (!group.title.trim()) issues.push({ tab: 'berkas', level: 'error', message: 'Ada kelompok yang belum punya judul.', groupId: group.id })

    /*
     * Id ganda tidak pernah terlihat di panel dan selalu terlihat di halaman
     * publik: React memakainya sebagai key, jadi dua berkas berid sama membuat
     * salah satunya hilang atau tertukar saat daftarnya diurutkan ulang.
     */
    if (seenIds.has(group.id)) error(`Id "${group.id}" dipakai lebih dari sekali.`)
    seenIds.add(group.id)

    group.items.forEach((item) => {
      if (seenIds.has(item.id)) error(`Id "${item.id}" dipakai lebih dari sekali.`)
      seenIds.add(item.id)

      if (!item.name.trim()) itemError(item, group.id, 'Ada berkas yang belum punya nama.')

      if (!item.href.trim()) {
        if (item.visible && group.visible) {
          itemWarn(item, group.id, `“${label(item)}” belum punya alamat, jadi akan tampil sebagai slot "Menyusul".`)
        }
        if (item.preview !== 'none') {
          itemError(item, group.id, `“${label(item)}” ditandai sebagai plat pratinjau tetapi belum punya alamat berkas.`)
        }
        return
      }

      if (item.kind === 'link' && !isHttpUrl(item.href)) {
        itemError(item, group.id, `Alamat “${label(item)}” harus berupa URL lengkap karena ditandai tautan luar.`)
      }

      if (item.kind === 'file' && !item.href.startsWith('/')) {
        itemError(item, group.id, `Alamat “${label(item)}” harus dimulai dengan / karena ditandai berkas situs.`)
      }

      /*
       * Berkas situs yang tidak tinggal di /assets/ hampir selalu salah ketik.
       * Tetap peringatan, bukan kesalahan: menaruh berkas di tempat lain di
       * dalam public/ itu sah, cuma bukan kebiasaan yang dipakai repo ini.
       */
      if (item.kind === 'file' && item.href.startsWith('/') && !item.href.startsWith('/assets/')) {
        itemWarn(item, group.id, `Alamat “${label(item)}” di luar /assets/. Pastikan berkasnya memang ada di sana.`)
      }

      if (item.preview !== 'none' && !isImagePath(item.href)) {
        itemError(item, group.id, `“${label(item)}” ditandai sebagai plat pratinjau, tetapi alamatnya bukan berkas gambar.`)
      }

      if (item.preview !== 'none' && item.kind === 'link') {
        itemError(item, group.id, `“${label(item)}” tidak bisa dipratinjau karena berkasnya tinggal di luar situs.`)
      }
    })
  })

  return {
    issues,
    errors: issues.filter((issue) => issue.level === 'error'),
    warnings: issues.filter((issue) => issue.level === 'warning'),
    success: issues.every((issue) => issue.level !== 'error'),
  }
}
